  "contradictory_card_ids": [
    "C77","C78","C79","C81","C83","C84","C86","C87"
  ],
  "prediction_basis_card_ids": [
    "C14","C36","C03","C11","C19","C13","C35","C17","C54","C65","C67"
  ],
  "claims": [
    {
      "claim": "Closest transferable human analogs with methoxyaryl and basic-amine motifs have measured oral bioavailability above 20%: vernakalant ~60% overall and 40.2% in extensive metabolizers, alizapride 72.5–89.7%, daridorexant 62% absolute, and nabumetone 32% in cirrhosis.",
      "card_ids": ["C14","C36","C03","C11","C19","C13","C35","C17"]
    },
    {
      "claim": "L4/L5 records show good absorption and high passive permeability without efflux for basic-amine/methoxyaryl compounds (trimethoxycinnamoyl piperazine readily absorbed; trihexyphenidyl Papp 46×10^-6 cm/s with ER 0.22; compound 5v Papp 18×10^-6 cm/s with ER 1.0), supporting adequate intestinal absorption for the query.",
      "card_ids": ["C54","C65","C67","C68","C70","C73","C75"]
    },
    {
      "claim": "L6 hepatic-clearance records for structurally related aryl-ketone/basic-amine and trimethoxyaryl compounds (tolperisone HLM CLint 1.27 ml/min/g liver; M03 RLM CLint 99 µL/min/mg; dextromethorphan HLM 41 µL/min/mg and human hepatocyte high clearance) indicate possible first-pass metabolism, but they are not direct F outcomes and do not establish F<20% for the query.",
      "card_ids": ["C81","C77","C78","C87"]
    },
    {
      "claim": "No L6 record provides affirmative evidence of F<20% for the query or a close analog; high intrinsic clearance alone is insufficient to overturn direct human F values above 20% for the closest chemotypes.",
      "card_ids": ["C81","C77","C78","C87"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "weakened",
      "card_ids": ["C77","C78","C79","C81","C83","C84","C86","C87"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental F, AUC, or Cmax data for the query molecule.",
    "No human hepatic clearance or metabolic stability measurement for the query; L6 records are for other molecules and mostly rat/microsomal.",
    "Relative contributions of intestinal absorption, gut-wall metabolism, and hepatic first-pass are unquantified for the query.",
    "Impact of full ionization at pH 7.4 and low logD (0.05) on in vivo permeability is not experimentally assessed.",
    "No data on O-demethylation or N-dealkylation rates for the query's trimethoxyaryl/pyrrolidine motif in human systems."
  ],
  "decision_summary": "Predicted high: direct human F values for the closest methoxyaryl/basic-amine analogs (vernakalant 40.2–81.8%, alizapride 72.5–89.7%, daridorexant 62%, nabumetone 32%) all exceed 20%, and L4/L5 records support adequate absorption and permeability without efflux. L6 hepatic-clearance records add a plausible first-pass liability but are indirect, species/assay-mismatched, and insufficient to establish F<20%; confidence is therefore moderated but the prediction remains high."
}

